#ifndef MAPDATA_H
#define MAPDATA_H

/* The board, generated by support/mkmap.py from the iOS app's map */

#define NTERR 42
#define NCONTINENTS 6
#define MAX_NEIGHBORS 6

/* The map's size on the 640x200 hires screen */
#define MAP_W 496
#define MAP_H 172

typedef struct {
  const char *name;
  unsigned char bonus;
} Continent;

typedef struct {
  const char *id;               /* the key in the game state's JSON */
  const char *name;
  unsigned char continent;
  unsigned char nneighbors;
  unsigned char neighbors[MAX_NEIGHBORS];
  unsigned short firstSpan, nspans;
  unsigned short badgeX;
  unsigned char badgeY;
} Territory;

/* One run of a territory's interior on map line y */
typedef struct {
  unsigned char y;
  unsigned short x0, x1;
} Span;

extern const Continent continents[NCONTINENTS];
extern const Territory territories[NTERR];
extern const Span spans[];
extern const unsigned long mapPlanesSize;
extern const unsigned char mapPlanes[];

#endif
